import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-92",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, CardComponent ],
    template: `
        <app-card heading="Feature 92" [disableTooltip]="true">
            <!-- disableTooltip here is the card's flag; pills carry their own -->
            <app-pill
                label="Plain"
                variant="warning"
                [disableTooltip]="true"
            />
            <app-pill
                [label]="title"
                [variant]="count > 3 ? 'success' : isActive ? 'warning' : 'info'"
                [disableTooltip]="!(isActive && count > 1)"
            />
            <app-pill [variant]="statusVariant" label="Nested" [disableTooltip]="false" />
            @if (disableTooltip) {
                <small>Own flag, unrelated to the pill input</small>
            }
        </app-card>
    `
})
